16	export class InfraConfigNormalizer {
17	  private readonly config: MedplumSourceInfraConfig;
18	  private readonly clients: { ssm: SSMClient };
19	
20	  constructor(config: MedplumSourceInfraConfig) {
21	    const { region } = config;
22	    if (!region) {
23	      throw new OperationOutcomeError(validationError("'region' must be defined as a string literal in config."));
24	    }
25	    if (!ssmClients[region]) {
26	      ssmClients[region] = new SSMClient({ region });
27	    }
28	    this.config = config;
29	    this.clients = { ssm: ssmClients[region] };
30	  }
31	
32	  async fetchParameterStoreSecret(key: string): Promise<string> {
33	    const response = await this.clients.ssm.send(
34	      new GetParameterCommand({
35	        Name: key,
36	        WithDecryption: true,
37	      })
38	    );
39	    const param = response.Parameter;
40	    if (!param) {
41	      throw new OperationOutcomeError(
42	        badRequest(
43	          `Key '${key}' not found. Make sure your key is correct and that it is defined in your Parameter Store.`
44	        )
45	      );
46	    }
47	    const paramValue = param.Value;
48	    if (!paramValue) {
49	      throw new OperationOutcomeError(
50	        badRequest(
51	          `Key '${key}' found but has no value. Make sure your key is correct and that it is defined in your Parameter Store.`
52	        )
53	      );
54	    }
55	    return paramValue;
56	  }
57	
58	  async fetchExternalSecret(externalSecret: ExternalSecret): Promise<ExternalSecretPrimitive> {
59	    assertValidExternalSecret(externalSecret);
60	    const { system, key, type } = externalSecret;
61	    let rawValue: ExternalSecretPrimitive;
62	    switch (system) {
63	      case 'aws_ssm_parameter_store': {
64	        rawValue = await this.fetchParameterStoreSecret(key);
65	        break;
66	      }
67	      default:
68	        throw new OperationOutcomeError(
69	          validationError(`Unknown system '${system}' for ExternalSecret. Unable to fetch the secret for key '${key}'.`)
70	        );
71	    }
72	    return normalizeFetchedValue(key, rawValue, type);
73	  }
74	
75	  async normalizeInfraConfigArray(currentVal: any[]): Promise<ExternalSecretPrimitive[] | Record<string, any>[]> {
76	    // ------ case 3a: primitives or `ExternalSecret`
77	    const firstEle = currentVal[0];
78	    let newArray: ExternalSecretPrimitive[] | Record<string, any>[];
79	    if ((typeof firstEle !== 'object' && firstEle !== null) || isExternalSecretLike(firstEle)) {
80	      newArray = new Array(currentVal.length) as ExternalSecretPrimitive[];
81	      for (let i = 0; i < currentVal.length; i++) {
82	        const currIdxVal = currentVal[i] as unknown as ExternalSecretPrimitive | ExternalSecret;
83	        if (typeof currIdxVal !== 'object') {
84	          newArray[i] = currIdxVal;
85	          continue;
86	        }
87	        const fetchedVal = await this.fetchExternalSecret(currIdxVal);
88	        newArray[i] = fetchedVal;
89	      }
90	    }
91	    // ------ case 3b: other objects (recurse)
92	    else {
93	      newArray = new Array(currentVal.length) as Record<string, any>[];
94	      for (let i = 0; i < currentVal.length; i++) {
95	        newArray[i] = await this.normalizeObjectInInfraConfig(currentVal[i]);
96	      }
97	    }
98	    return newArray;
99	  }
100	
101	  async normalizeValueForKey(obj: Record<string, any>, key: string): Promise<void> {
102	    const currentVal = obj[key];
103	    // cases:
104	    // --- case 1: primitive
105	    if (typeof currentVal !== 'object') {
106	      obj[key] = currentVal;
107	    }
108	    // --- case 2: object conforming to `ExternalSecret` schema
109	    else if (isExternalSecretLike(currentVal)) {
110	      obj[key] = await this.fetchExternalSecret(currentVal);
111	    }
112	    // --- case 3: an array of:
113	    else if (Array.isArray(currentVal)) {
114	      obj[key] = await this.normalizeInfraConfigArray(currentVal);
115	    }
116	    // --- case 4: other object (recurse)
117	    else if (typeof currentVal === 'object') {
118	      obj[key] = await this.normalizeObjectInInfraConfig(currentVal);
119	    }
120	  }
121	
122	  async normalizeObjectInInfraConfig(obj: Record<string, any>): Promise<Record<string, any>> {
123	    const normalizedObj = { ...obj };
124	    // walk config object
125	    for (const key of Object.keys(normalizedObj)) {
126	      await this.normalizeValueForKey(normalizedObj, key);
127	    }
128	    return normalizedObj;
129	  }
130	
131	  async normalizeConfig(): Promise<MedplumInfraConfig> {
132	    return this.normalizeObjectInInfraConfig(this.config) as Promise<MedplumInfraConfig>;
133	  }
134	}
