136	export function normalizeFetchedValue(
137	  key: string,
138	  rawValue: ExternalSecretPrimitive,
139	  expectedType: ExternalSecretPrimitiveType
140	): ExternalSecretPrimitive {
141	  const typeOfVal = typeof rawValue;
142	  // Return raw type if type is string and value is of type string, or if type isn't string and typeof val isn't string
143	  if (!VALID_PRIMITIVE_TYPES.includes(typeOfVal)) {
144	    throw new OperationOutcomeError(
145	      validationError(
146	        `Invalid value found for type; expected either ${VALID_PRIMITIVE_TYPES.join(', or')} but got ${typeOfVal}`
147	      )
148	    );
149	  }
150	  if (typeOfVal === expectedType) {
151	    return rawValue;
152	  } else if (typeOfVal === 'string' && expectedType === 'boolean') {
153	    const normalized = (rawValue as string).toLowerCase() as 'true' | 'false';
154	    if (normalized !== 'true' && normalized !== 'false') {
155	      throw new OperationOutcomeError(
156	        validationError(`Invalid value found for key '${key}'; expected boolean value but got '${rawValue}'`)
157	      );
158	    }
159	    return normalized === 'true';
160	  } else if (typeOfVal === 'string' && expectedType === 'number') {
161	    const parsed = Number.parseInt(rawValue as string, 10);
162	    if (Number.isNaN(parsed)) {
163	      throw new OperationOutcomeError(
164	        validationError(`Invalid value found for key '${key}'; expected integer value but got '${rawValue}'`)
165	      );
166	    }
167	    return parsed;
168	  } else {
169	    throw new OperationOutcomeError(
170	      validationError(`Invalid value found for type; expected ${expectedType} value but got value of type ${typeOfVal}`)
171	    );
172	  }
173	}
