175	export function isExternalSecretLike(obj: Record<string, any>): obj is ExternalSecret {
176	  return (
177	    typeof obj === 'object' &&
178	    typeof obj.system === 'string' &&
179	    typeof obj.key === 'string' &&
180	    typeof obj.type === 'string'
181	  );
182	}
183	
184	export function isExternalSecret(obj: Record<string, any>): obj is ExternalSecret {
185	  return (
186	    typeof obj === 'object' &&
187	    typeof obj.system === 'string' &&
188	    typeof obj.key === 'string' &&
189	    VALID_PRIMITIVE_TYPES.includes(obj.type)
190	  );
191	}
192	
193	export function assertValidExternalSecret(obj: Record<string, any>): asserts obj is ExternalSecret {
194	  if (!isExternalSecret(obj)) {
195	    throw new OperationOutcomeError(
196	      validationError('obj is not a valid `ExternalSecret`, must contain a valid `system`, `key`, and `type` prop.')
197	    );
198	  }
199	}
